fn check_push(model: &str, cname: &str) {
    let lines = read_lines(&format!("push_{model}_{cname}.txt"));
    let cutter = cutter_from_spec(&lines[0]);
    let surf = load_model(model);
    // parse fibers: F dir p1x p1y p2x p2y z n, followed by n lines of I lower upper lt ut
    let mut fibers: Vec<(char, Fiber, Vec<Vec<f64>>)> = Vec::new();
    for l in &lines[1..] {
        if let Some(rest) = l.strip_prefix("F ") {
            let dir = rest.chars().next().unwrap();
            let v = nums(&rest[2..]);
            let f = Fiber::new(Point::new(v[0], v[1], v[4]), Point::new(v[2], v[3], v[4]));
            fibers.push((dir, f, Vec::new()));
        } else if let Some(rest) = l.strip_prefix("I ") {
            fibers.last_mut().unwrap().2.push(nums(rest));
        }
    }
    let mut checked = 0;
    for (dir, fdir) in [('x', FiberDirection::X), ('y', FiberDirection::Y)] {
        let mut bpc = BatchPushCutter::new(&surf, cutter.as_ref(), fdir);
        let refs: Vec<&(char, Fiber, Vec<Vec<f64>>)> = fibers.iter().filter(|f| f.0 == dir).collect();
        for (_, f, _) in &refs {
            bpc.append_fiber(f.clone());
        }
        bpc.run();
        for (got, (_, _, want)) in bpc.get_fibers().iter().zip(&refs) {
            assert_eq!(got.ints.len(), want.len(), "{cname}: interval count on fiber {}", got);
            for (i, w) in got.ints.iter().zip(want) {
                assert!((i.lower - w[0]).abs() < TOL, "{cname}: lower {} vs {}", i.lower, w[0]);
                assert!((i.upper - w[1]).abs() < TOL, "{cname}: upper {} vs {}", i.upper, w[1]);
                assert_eq!(i.lower_cc.cc_type as u8 as f64, w[2], "{cname}: lower cc type");
                assert_eq!(i.upper_cc.cc_type as u8 as f64, w[3], "{cname}: upper cc type");
                checked += 1;
            }
        }
    }
    println!("push {model} {cname}: {checked} intervals match");
    assert!(checked > 0);
}

