/// Parse loops after a `K kind` line.
fn parse_loops(lines: &[String], kind: &str) -> Vec<Vec<Point>> {
    let start = lines.iter().position(|l| l == &format!("K {kind}")).unwrap();
    let n = nums(&lines[start + 1])[0] as usize;
    let mut idx = start + 2;
    let mut loops = Vec::new();
    for _ in 0..n {
        let len = nums(&lines[idx])[0] as usize;
        idx += 1;
        let lp = (0..len)
            .map(|k| {
                let v = nums(&lines[idx + k]);
                Point::new(v[0], v[1], v[2])
            })
            .collect();
        idx += len;
        loops.push(lp);
    }
    loops
}

/// True if `a` and `b` are the same cyclic sequence of points (any starting point).
fn same_loop(a: &[Point], b: &[Point], tol: f64) -> bool {
    if a.len() != b.len() {
        return false;
    }
    if a.is_empty() {
        return true;
    }
    (0..b.len()).any(|shift| {
        (0..a.len()).all(|k| (a[k] - b[(k + shift) % b.len()]).norm() < tol)
    })
}

fn assert_same_loops(got: &[Vec<Point>], want: &[Vec<Point>], what: &str) {
    assert_eq!(got.len(), want.len(), "{what}: number of loops");
    let mut used = vec![false; got.len()];
    for w in want {
        let found = (0..got.len()).find(|&k| !used[k] && same_loop(&got[k], w, 1e-8));
        let k = found.unwrap_or_else(|| panic!("{what}: no matching loop for a reference loop of {} points", w.len()));
        used[k] = true;
    }
    let npts: usize = want.iter().map(Vec::len).sum();
    println!("{what}: {} loops, {npts} points match", want.len());
}

fn check_waterline(model: &str, cname: &str) {
    let lines = read_lines(&format!("waterline_{model}_{cname}.txt"));
    let cutter = cutter_from_spec(&lines[0]);
    let zs = nums(&lines[1]);
    let surf = load_model(model);
    let mut wl = Waterline::new(&surf, cutter.as_ref());
    wl.set_z(zs[0]);
    wl.set_sampling(zs[1]);
    wl.run();
    assert_same_loops(wl.get_loops(), &parse_loops(&lines, "simple"), &format!("{model} {cname} simple"));
    wl.run2();
    assert_same_loops(wl.get_loops(), &parse_loops(&lines, "smart"), &format!("{model} {cname} smart"));

    let mut awl = AdaptiveWaterline::new(&surf, cutter.as_ref());
    awl.set_z(zs[0]);
    awl.set_sampling(zs[1]);
    awl.run();
    assert_same_loops(awl.get_loops(), &parse_loops(&lines, "adaptive_simple"), &format!("{model} {cname} adaptive simple"));
    awl.run2();
    assert_same_loops(awl.get_loops(), &parse_loops(&lines, "adaptive_smart"), &format!("{model} {cname} adaptive smart"));
}

