fn check_path(model: &str, cname: &str) {
    let lines = read_lines(&format!("path_{model}_{cname}.txt"));
    let cutter = cutter_from_spec(&lines[0]);
    let z = nums(&lines[1])[0];
    let surf = load_model(model);
    let pidx = lines.iter().position(|l| l == "P").unwrap();
    let mut path = Path::new();
    for l in &lines[pidx + 1..] {
        let v = nums(l);
        path.append_line(Line::new(Point::new(v[0], v[1], z), Point::new(v[2], v[3], z)));
    }
    let parse = |kind: &str| -> Vec<Vec<f64>> {
        let s = lines.iter().position(|l| l.starts_with(&format!("K {kind} "))).unwrap();
        let n = nums(&lines[s])[0] as usize;
        lines[s + 1..s + 1 + n].iter().map(|l| nums(l)).collect()
    };
    let compare = |got: &[CLPoint], want: &[Vec<f64>], what: &str| {
        assert_eq!(got.len(), want.len(), "{what}: number of points");
        for (g, w) in got.iter().zip(want) {
            assert!((g.pos - Point::new(w[0], w[1], w[2])).norm() < TOL, "{what}: {} vs {:?}", g.pos, w);
        }
        println!("{what}: {} points match", got.len());
    };

    let mut pdc = PathDropCutter::new(&surf, cutter.as_ref());
    pdc.set_path(&path);
    pdc.set_z(z);
    pdc.set_sampling(0.1);
    pdc.run();
    compare(pdc.get_cl_points(), &parse("uniform"), &format!("path {cname} uniform"));

    let mut apdc = AdaptivePathDropCutter::new(&surf, cutter.as_ref());
    apdc.set_path(&path);
    apdc.set_z(z);
    apdc.set_sampling(0.1);
    apdc.set_min_sampling(0.01);
    apdc.run();
    compare(apdc.get_cl_points(), &parse("adaptive"), &format!("path {cname} adaptive"));
}

